UPDATE articles SET
    title = 'فقدان الكملك أو تلفه: بدل ضائع بلا رسوم — الخطوات الرسمية',
    intro = '',
    details = '<p>اذهب اليوم إلى أقرب مركز شرطة ونظّم محضر ضياع أو سرقة (kayıp/çalıntı tutanağı)، ثم راجع مديرية الهجرة في ولايتك (İl Göç İdaresi Müdürlüğü) — والبطاقة البديلة تُصدَر لك دون أي رسم.</p>

<p><strong>وقبل أن تكمل: هذه الصفحة عن بطاقة الحماية المؤقتة (الكملك) وحدها.</strong> إن كان ما ضاع منك بطاقة إقامة (ikamet izni) فالقواعد مختلفة تماماً: هناك رسوم تُدفع فعلاً، وهناك قوائم أوراق منشورة، والمسار غير هذا المسار. راجع <a href="/article/lost-residence-card">بدل بطاقة الإقامة الضائعة</a>، أو <a href="/article/kimlik-temporary-protection-syria-2026">الفرق بين الكملك والإقامة</a> إن لم تكن متأكداً أي وثيقة تحمل. أكثر الأخطاء كلفةً في هذا الباب أن يأخذ صاحب إقامة قاعدة الكملك، أو أن تُلصَق بالكملك قاعدة الإقامة — ومن هنا جاء الرقم الخاطئ الذي كانت هذه الصفحة تنشره.</p>

<h2>لا تدفع مقابل بطاقة بديلة</h2>

<p>نصّ لائحة الحماية المؤقتة صريح: بطاقة الحماية المؤقتة (Geçici Koruma Kimlik Belgesi) تُنظَّم دون أن تخضع لأي أجر (المادة 22/3). والفقرة التي تليها في المادة نفسها تقول إنّ البطاقة التالفة أو الضائعة يُنظَّم بدلاً عنها بطاقة جديدة (المادة 22/4) — بالحكم نفسه، وبالمجانية نفسها. ونصّ اللائحة كاملاً منشور على موقع التشريعات الرسمي: <a href="https://www.mevzuat.gov.tr/MevzuatMetin/21.5.20146883.pdf">لائحة الحماية المؤقتة</a>.</p>

<p>وصفحة <a href="https://www.goc.gov.tr/duzenlecek-belgelerbelge">الوثائق التي تُصدرها رئاسة إدارة الهجرة</a> تكرّر ذلك بجملة واحدة: البطاقة لا تخضع لأي رسم ولا أجر. لا يوجد في اللائحة ولا في صفحات الإدارة أي استثناء للضياع أو للتلف، ولا أي مبلغ مذكور من قريب أو بعيد.</p>

<p>إن كنت قرأت في مكان ما رقماً محدّداً باعتباره «رسم بدل الكملك الضائع» فهو غير صحيح ولا سند له. ومن يطلب منك مالاً — سمساراً كان أو «معقّباً» — فهو لا ينقل إليك رسماً رسمياً، بل يبيعك خدمة لا تحتاج إليها أصلاً. ولن يُطلب منك في هذه المعاملة إيصال دفع من بنك ولا من البريد، لأنه لا يوجد ما يُدفع.</p>

<h2>الخطوات بالترتيب</h2>

<ol>
<li><strong>محضر في الشرطة.</strong> رئاسة إدارة الهجرة تذكر في <a href="https://www.goc.gov.tr/gecici-koruma-sss">أسئلتها الشائعة عن الحماية المؤقتة</a> أنّ من فقد بطاقته أو سُرقت منه عليه أن ينظّم محضر ضياع أو سرقة في الأمن، ثم يراجع مديرية الهجرة في الولاية. والنص نفسه منشور بالعربية على <a href="https://ar.goc.gov.tr/%D8%A7%D9%84%D8%AD%D9%85%D8%A7%D9%8A%D8%A9-%D8%A7%D9%84%D9%85%D8%A4%D9%82%D8%AA%D8%A9-sss">صفحة الإدارة العربية</a>، ويمكنك أن تُظهره لمن يجادلك.</li>
<li><strong>إن لم يُنظَّم المحضر لأي سبب: إعلان في جريدة.</strong> النص الرسمي يقول إنه في حال عدم تنظيم المحضر، يُنشر إعلان في جريدة محلية أو وطنية، ثم تُراجَع مديرية الهجرة. لاحظ أنّ الشرط هو ألّا يوجد محضر — لا أن يرفض المخفر تحديداً. فسواء رُفض طلبك، أو وجدت المركز مغلقاً، أو صُرفت وقيل لك عُد لاحقاً، فطريق الإعلان مفتوح لك.</li>
<li><strong>مراجعة مديرية الهجرة في الولاية.</strong> إلى المديرية التي أنت مسجّل لديها، ومعك المحضر أو الإعلان — والبطاقة التالفة معهما إن كانت تالفة لا ضائعة. وإن كان معك ما يعرّف بك من وثائق أخرى — جواز سفر، وثيقة سورية، أو حتى صورة واضحة عن بطاقتك القديمة — فاصطحبها؛ لا تُغني عن المحضر، لكنها تسهّل إثبات هويتك على الشباك.</li>
<li><strong>الإفادة وتدوينها.</strong> اللائحة تُلزمك بتقديم إيضاح (açıklama) عن كيفية الضياع أو التلف، ويُدوَّن هذا في ملفك (المادة 22/4). وهو كلام تقوله هناك، لا ورقة تجهّزها مسبقاً. قل ما حدث كما حدث؛ لا شيء في النص يرتّب عقوبة على الضياع نفسه.</li>
<li><strong>إصدار البدل.</strong> تُنظَّم بطاقة جديدة مكان الضائعة أو التالفة (المادة 22/4).</li>
<li><strong>احتفظ بورقتك حتى تستلم الجديدة.</strong> المحضر أو الإعلان هو ما بيدك إلى أن تصل البطاقة — احمله وصوّره، والتفصيل في آخر هذه الصفحة.</li>
</ol>

<h3>البطاقة التالفة حالة مختلفة عن الضائعة</h3>

<p>إذا كانت بطاقتك ممزّقة أو مطموسة لا ضائعة، فالمادة 22/4 تقول إنّ البطاقة التالفة <strong>تُلغى</strong> أولاً ثم يُنظَّم بدل عنها. لذلك احمل البطاقة التالفة معك ولا ترمِها ولا تتخلّص منها: النص يجعل إلغاءها خطوة سابقة على إصدار البدل. (أمّا تسليم البطاقة إلى الإدارة فاللائحة لا تنصّ عليه إلا في حالة واحدة مختلفة: انتهاء الحماية المؤقتة، حيث تفقد البطاقة صلاحيتها وتُستردّ من صاحبها — المادة 22/5.)</p>

<h2>أين تذهب</h2>

<p>المراجعة تكون لمديرية الهجرة في الولاية التي أنت مسجّل فيها. هذا هو كل ما يذكره الجواب الرسمي الخاص بالبطاقة الضائعة: «مديرية الهجرة في الولاية»، بلا تخصيص وحدة بعينها.</p>

<p>وإن كنت في إسطنبول فانتبه: مركزا التنسيق في كومكابي وسلطان بيلي مذكوران في الصفحة الرسمية نفسها، لكن في جواب آخر يخصّ <strong>التسجيل</strong> تحت الحماية المؤقتة، لا في جواب البطاقة الضائعة. لا تعتبرهما عنوان معاملتك ولا تقطع المدينة إليهما قبل أن تسأل أي وحدة تستقبل حالات الضياع اليوم — فإسطنبول توزّع معاملاتها على أكثر من نقطة، وكلّ نقطة لمعاملات بعينها.</p>

<p>لبقية الولايات، تُعرض العناوين في صفحة <a href="https://www.goc.gov.tr/il-mudurlukleri">مديريات الولايات</a> على موقع الإدارة، لكن الصفحة لا تُظهر أي عنوان قبل أن تختار الولاية ثم القضاء من القائمتين المنسدلتين. لا تحكم على الصفحة بأنها فارغة.</p>

<h2>ضياع البطاقة لا يُنهي حمايتك المؤقتة</h2>

<p>هذه أهم جملة في الصفحة، وقلّ من يقولها لمن ضاعت بطاقته: <strong>ضياع الورقة ليس سبباً لانتهاء حمايتك المؤقتة.</strong> اللائحة تعدّد أسباب انتهاء الحماية فرداً فرداً في المادة 12/1، وهي محصورة في ستّ حالات: أن تغادر تركيا بإرادتك، أن تستفيد من حماية دولة ثالثة، أن تُقبل في دولة ثالثة لأسباب إنسانية أو ضمن إعادة التوطين أو تخرج إليها، الوفاة، أن تكتسب حق البقاء بطريق آخر من طرق الإقامة القانونية في القانون، أو أن تكتسب الجنسية التركية. ليس بينها ضياع البطاقة ولا تلفها.</p>

<p>وما تبقّى في المادة نفسها حالتان لا ثالث لهما: إلغاء الحماية إن تبيّن لاحقاً أنّ الشخص كان يجب أن يُستثنى من نطاقها أصلاً (المادة 12/2)، وإلغاؤها لمن يتخلّف عن التبليغ الدوري ثلاث مرات متتالية بلا عذر (المادة 12/3). لا شيء غير ذلك.</p>

<p>بل إنّ التسجيل نفسه لا يتوقّف على إبراز وثيقة هوية: المادة 21/2/ج تنصّ على أنّ من لا يستطيع تقديم وثيقة تثبت هويته تُعتمد إفادته حتى يثبت العكس. وبياناتك — بما فيها بصمتك وصورتك — مسجّلة في قاعدة بيانات مركزية ومحفوظة إلكترونياً في ملفك (المادة 21/2). الورقة دليل على تسجيلك، وليست هي التسجيل. اذهب واطلب بدلها بهدوء.</p>

<h2>لا تؤجّل: ما تخسره ليس البطاقة وحدها</h2>

<p>هذا لا يعني أن تؤجّل. البطاقة هي ما يمنحك حق البقاء في تركيا (المادة 25/1)، وإن كانت لا تعادل الإقامة ولا الوثائق التي تقوم مقامها. وضياعها لا يوقف أياً من التزاماتك ولا يؤجّل مواعيدها.</p>

<p>وهناك سبب ثانٍ للاستعجال بالمحضر تحديداً: البطاقة الضائعة قد تقع في يد غيرك وتُستعمل باسمك. المحضر هو ما يثبّت تاريخ الضياع ويُظهر أنك بلّغت عنه قبل أي استعمال لاحق لها — فلا تؤخّره ولو تأخّرت مراجعتك للمديرية أياماً.</p>

<p>والالتزام الذي يصطدم فعلاً بضياع البطاقة هو <strong>التبليغ الدوري (bildirim)</strong>: أنت مُلزَم بالتبليغ بالشكل والمواعيد التي تحدّدها الولاية (المادة 33/2)، ومن يتخلّف عن هذا الالتزام ثلاث مرات متتالية بلا عذر تُلغى حمايته المؤقتة بقرار من الولاية (المادة 12/3). فإن ضاعت بطاقتك ولك موعد تبليغ قريب، أخبر المديرية بالضياع <strong>قبل</strong> الموعد لا بعده. وانتبه إلى الفرق: هذا هو التبليغ الدوري المفروض عليك، لا زيارتك للمديرية من أجل البطاقة — الزيارة من أجل البدل لا تُعدّ تخلّفاً عن شيء ولا تُحتسب عليك.</p>

<p>وبقية التزاماتك قائمة كما هي: الإقامة في الولاية المحدّدة لك، وتبليغ تغيّر العنوان والحالة المدنية والولادات والوفيات خلال عشرين يوم عمل، وتبليغ وضعك الوظيفي ودخلك وأملاكك خلال ثلاثين يوماً (المادة 33/2). وإن دُعيت إلى جهة ولم تستجب، يجوز إحضارك بواسطة قوات الأمن دون دعوة جديدة (المادة 34/2).</p>

<h2>ريثما تصلك البطاقة الجديدة</h2>

<p>رقم الأجنبي (yabancı kimlik numarası) يُمنح لمن تُصدَر لهم بطاقة الحماية المؤقتة، بموجب قانون خدمات النفوس رقم 5490 (المادة 22/2)، وهو مقيَّد باسمك في سجلات الدولة لا في الورقة وحدها. لكن انتبه إلى أنّ كثيراً من المعاملات تُطلب فيها البطاقة نفسها لا الرقم — من مراجعة المستشفى إلى التسجيل المدرسي إلى معاملات البنك — وأنّ اللائحة تجيز لك إبرام عقود الاشتراك، ومنها خدمات الاتصال الإلكتروني، ببطاقتك (المادة 26/3)، فبدونها قد تتعطّل هذه المعاملات.</p>

<p>واللائحة لا تنصّ على أي وثيقة مؤقتة تُسلَّم لحامل الحماية المؤقتة ريثما تصدر بطاقته الجديدة. هذا يختلف عن بطاقة الإقامة، حيث ينصّ القانون 6458 على أنّ من يتقدّم بطلب <strong>تمديد</strong> إقامته تُسلَّم له وثيقة غير خاضعة للرسم (harca tabi olmayan bir belge) يبقى بها مقيماً بشكل نظامي حتى صدور القرار (المادة 24/2). وهذا نصّ موضعه باب تمديد الإقامة، فلا يمتدّ إلى الكملك ولا إلى غير طلبات التمديد. فإن أعطتك المديرية ورقة أو ورقة موعد، احتفظ بها وصوّرها بهاتفك. واسأل قبل أن تغادر الشباك إن كان لطلبك رقم متابعة أو رقم معاملة، واكتبه عندك — فهو ما تراجع به لاحقاً دون أن تعيد شرح قصتك من أوّلها.</p>

<p><strong>واحتفظ بمحضر الشرطة أو بإعلان الجريدة معك، وصوّره.</strong> احفظ الصورة في مكان تصل إليه بلا إنترنت. هو الورقة الوحيدة التي تُظهر أنك بلّغت عن الضياع، وقد تُطلب منك بطاقتك قبل أن تصلك الجديدة. وإن أوقفتك الشرطة وأنت بلا بطاقة، فأظهر ما معك واذكر أنك بلّغت وأنك راجعت المديرية — وتفصيل حقوقك في <a href="/article/police-station-rights">حقوقك إن أوقفتك الشرطة</a>.</p>

<p>وإن لم تكن تتقن التركية بما يكفي لإتمام المعاملة، فخدمة الترجمة تُقدَّم <strong>مجاناً</strong> في معاملات هذه اللائحة عند تعذّر التفاهم (المادة 31/1). اطلبها، ولا تدفع لمرافق يقول لك إنه «يفهم عليهم».</p>

<h2>ما يختلف بحسب الولاية وما لم نتمكن من تأكيده</h2>

<ul>
<li><strong>قائمة الأوراق.</strong> لا اللائحة ولا صفحات إدارة الهجرة تنشر قائمة أوراق لبدل بطاقة الحماية المؤقتة. الشيء الوحيد المذكور رسمياً هو محضر الشرطة أو الإعلان. أمّا الصور الشخصية — وتُطلب بيومترية حيث تُطلب — وبيان العنوان وصور الوثائق القديمة فتُطلب في مديريات ولا تُطلب في غيرها. اسأل مديريتك قبل أن تذهب.</li>
<li><strong>العنوان المسجّل في ملفك.</strong> إن كنت انتقلت ولم تبلّغ بعنوانك الجديد، فقد يسبّب الاختلاف بين عنوانك الفعلي والمسجّل تأخيراً أو طلب أوراق إضافية. عالج الأمرين في مراجعة واحدة إن أمكن — وتذكّر أنّ تبليغ تغيّر العنوان واجب أصلاً خلال عشرين يوم عمل (المادة 33/2).</li>
<li><strong>الوحدة التي تستقبلك، وخاصة في إسطنبول.</strong> الجواب الرسمي عن البطاقة الضائعة لا يسمّي إلا «مديرية الهجرة في الولاية». وتوزيع المعاملات داخل الولاية الواحدة شأن محلي يتغيّر، فاسأل قبل أن تتحرّك.</li>
<li><strong>الموعد.</strong> هل يلزمك موعد مسبق أم تُراجع مباشرة؟ لم نجد نصاً رسمياً يحسم ذلك في حالة الضياع. نظام المواعيد الإلكتروني للهجرة موجود ومذكور رسمياً في سياق تحديث البيانات، لا في سياق البدل الضائع.</li>
<li><strong>مدة الإصدار.</strong> لا مدة منصوصة في اللائحة، ولم نجد رقماً رسمياً منشوراً. لا تصدّق من يعدك بيوم أو بأسبوع محدّد.</li>
<li><strong>إعلان الجريدة.</strong> النص الرسمي يقبله بديلاً عن المحضر، لكنه لا يحدّد جريدة بعينها ولا كلفة ولا صيغة. وما تدفعه للجريدة أجر خاص بها لا رسم للدولة. اسأل مديريتك أي إعلان تقبله قبل أن تدفع لأي جهة.</li>
<li><strong>رقم الأجنبي على البطاقة الجديدة.</strong> لا نصّ يؤكد بقاء الرقم نفسه بعد إعادة الإصدار. تحقّق من الرقم لحظة استلام البطاقة، وقبل أن تغادر الشباك.</li>
<li><strong>الأطفال والعائلة.</strong> لكل شخص بطاقته. لم نجد نصاً يحدّد ما إذا كان يمكن لربّ الأسرة إنهاء بدل بطاقة أحد أفرادها بالوكالة في حالة الضياع.</li>
</ul>

<h2>بعد أن تستلم البطاقة الجديدة</h2>

<p>راجع الجهات التي كانت تحتفظ برقم بطاقتك أو بصورتها — البنك، الجامعة أو المدرسة، وجهة عملك إن كنت مسجّلاً — وحدّث ما لديها إن تغيّر شيء على البطاقة الجديدة. هذه ليست خطوة تفرضها اللائحة، لكنها ما يمنع تعطّل معاملة لاحقة لسبب لا علاقة له بالهجرة.</p>

<p>ثم صوّر البطاقة الجديدة واحفظ الصورة في مكان آمن تصل إليه بلا إنترنت. الصورة الواضحة عن بطاقتك هي أسرع ما يسهّل عليك الإجراء كلّه إن تكرّر الضياع — ولن تجد وقتاً لتصويرها بعد أن تضيع.</p>

<h2>روابط تنفعك</h2>

<ul>
<li><a href="/article/kimlik-temporary-protection-syria-2026">ما هو الكملك، والفرق بينه وبين الإقامة</a> — ابدأ من هنا إن لم تكن متأكداً أي وثيقة ضاعت منك.</li>
<li><a href="/article/lost-residence-card">بدل بطاقة الإقامة الضائعة</a> — المسار الآخر تماماً، وفيه رسوم فعلية.</li>
<li><a href="/article/kimlik-data-update">تحديث بيانات الكملك والعنوان</a> — وتذكّر: لا يوجد أصلاً شيء اسمه «تجديد الكملك»، فالقيد إمّا نشط وإمّا مُلغى، والموجود هو تحديث البيانات (Veri Güncelleme). إن كان عنوانك تغيّر أيضاً، عالج الأمرين في مراجعة واحدة.</li>
<li><a href="/article/kimlik-appointments">حجز مواعيد الهجرة لحاملي الكملك</a></li>
<li><a href="/article/identity-kimlik-iptal-v160">إبطال الكملك وأسبابه</a> — إن اكتشفت أنّ بطاقتك مُبطَلة لا ضائعة، فالمسار مختلف تماماً.</li>
<li><a href="/article/police-station-rights">حقوقك إن أوقفتك الشرطة</a> — يفيدك إن أُوقفت وأنت بلا بطاقة.</li>
</ul>',
    documents = ARRAY['محضر ضياع أو سرقة من الشرطة (kayıp/çalıntı tutanağı) — هذا أو بديله في السطر التالي هو الشيء الوحيد الذي تذكره الإدارة صراحةً لهذه المعاملة.', 'أو إعلان في جريدة محلية أو وطنية، إن لم يُنظَّم المحضر لأي سبب.', 'البطاقة التالفة نفسها إن كانت تالفة لا ضائعة — المادة 22/4 تجعل إلغاءها خطوة سابقة على إصدار البدل.', 'إيضاح (açıklama) تقوله في المديرية عن كيفية الضياع أو التلف، يُدوَّن في ملفك (المادة 22/4) — ليس ورقة تجهّزها مسبقاً.', 'لا اللائحة ولا صفحات إدارة الهجرة تنشر قائمة أوراق لهذه المعاملة — اسأل مديريتك عن الصور وبيان العنوان قبل أن تذهب.', 'لا إيصال دفع ولا وصل بنك: البطاقة البديلة لا تخضع لأي رسم ولا أجر.', 'وثيقة تعريف بديلة إن وُجدت: جواز سفر، أو وثيقة سورية، أو صورة واضحة عن الكملك القديم']::text[],
    tips = ARRAY['البدل مجاني بنصّ المادة 22/3: من يطلب منك مالاً مقابل كملك بديل لا ينقل إليك رسماً رسمياً.', 'ضياع البطاقة ليس من أسباب انتهاء الحماية المؤقتة المعدودة في المادة 12/1 — حمايتك لا تسقط بضياع ورقة.', 'إن كان ما ضاع منك بطاقة إقامة (ikamet izni) لا كملك، فالقواعد مختلفة تماماً وهناك رسوم تُدفع فعلاً.', 'إن كان لك موعد تبليغ دوري قريب، أخبر المديرية بالضياع قبله لا بعده (المادة 12/3).', 'لا تصدّق من يعدك بمدة إصدار محدّدة؛ لا مدة منصوصة في اللائحة ولا رقم رسمي منشور.', 'احمل البطاقة التالفة ولا ترمِها — المادة 22/4 تقضي بإلغائها قبل إصدار البدل.', 'احتفظ من الآن بصورة رقمية واضحة لكملكك — تُسهّل إثبات هويتك وتُسرّع إصدار البدل عند الفقدان', 'اطلب ورقة متابعة واحفظ رقم الطلب إن أعطتك المديرية رقماً', 'إن تغيّر عنوانك الفعلي عمّا هو مسجَّل في ملفك فقد يتأخّر الإجراء أو تُطلب أوراق إضافية — عالج الأمرين في مراجعة واحدة', 'البطاقة الضائعة قد تُستعمل باسمك، وهذا سبب إضافي لعدم تأجيل المحضر']::text[],
    fees = 'البطاقة البديلة نفسها مجانية بنصّ المادة 22/3 من لائحة الحماية المؤقتة — لا رسم ولا أجر. وما قد تدفعه فعلاً هو كلفة خارجية لا علاقة لها بالدولة: صور شخصية من استوديو إن طلبتها مديريتك، أو ترجمة وتصديق وثيقة إن لزمت. من يطلب منك مالاً مقابل البطاقة نفسها يبيعك ما تمنحه الدولة مجاناً.',
    seo_title = 'فقدان الكملك: بدل ضائع بلا رسوم — الخطوات الرسمية',
    seo_description = 'ضاع كملكك أو تلف؟ محضر شرطة أو إعلان جريدة ثم مديرية الهجرة، والبدل بلا أي رسم بنصّ المادة 22/3. وضياع البطاقة لا يُنهي حمايتك المؤقتة.',
    last_update = CURRENT_DATE
WHERE slug = 'lost-kimlik-replacement';

-- الصفحتان المدموجتان تُحذفان بعد نقل حقائقهما
DELETE FROM articles WHERE slug IN ('kimlik-lost-damaged', 'identity-lost-card-replacement');

