-- التحقّق — الأول يجب أن يرجع صفّاً واحداً، والثاني صفر صفوف
SELECT slug, length(details) AS details_len,
       coalesce(array_length(documents,1),0) AS docs,
       coalesce(array_length(tips,1),0) AS tips_n,
       (fees IS NOT NULL) AS has_fees, last_update
FROM articles WHERE slug = 'lost-kimlik-replacement';

